-- Plantilla de perfiles para congregaciones nuevas y existentes (copia de los perfiles de Villa Real).
-- Solo AGREGA: nunca modifica ni borra perfiles existentes de una congregación.

CREATE TABLE IF NOT EXISTS public.perfiles_plantilla (
  nombre text PRIMARY KEY,
  descripcion text,
  icono text NOT NULL,
  color text,
  permisos jsonb NOT NULL,
  orden integer NOT NULL DEFAULT 0
);

ALTER TABLE public.perfiles_plantilla ENABLE ROW LEVEL SECURITY;
-- Sin políticas: solo la leen las funciones del servidor (SECURITY DEFINER).

