CREATE OR REPLACE FUNCTION public.aplicar_plantilla_perfiles(_congregacion_id uuid)
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n integer;
BEGIN
  INSERT INTO public.perfiles_permisos (congregacion_id, nombre, descripcion, icono, color, permisos, es_sistema)
  SELECT _congregacion_id, t.nombre, t.descripcion, t.icono, t.color, t.permisos, false
  FROM public.perfiles_plantilla t
  WHERE NOT EXISTS (
    SELECT 1 FROM public.perfiles_permisos p
    WHERE p.congregacion_id = _congregacion_id AND lower(p.nombre) = lower(t.nombre)
  )
  ORDER BY t.orden;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$$;

REVOKE ALL ON FUNCTION public.aplicar_plantilla_perfiles(uuid) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.aplicar_plantilla_perfiles(uuid) TO service_role;

-- Congregaciones nuevas: reciben los perfiles al crearse.
CREATE OR REPLACE FUNCTION public.trg_congregacion_perfiles_plantilla()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM public.aplicar_plantilla_perfiles(NEW.id);
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS congregacion_perfiles_plantilla ON public.congregaciones;
CREATE TRIGGER congregacion_perfiles_plantilla
  AFTER INSERT ON public.congregaciones
  FOR EACH ROW EXECUTE FUNCTION public.trg_congregacion_perfiles_plantilla();

-- Congregaciones existentes: se agregan los que falten (no se toca ninguno existente).
SELECT public.aplicar_plantilla_perfiles(id) FROM public.congregaciones;
